/**
 * Route session state machine — pure computation layer.
 *
 * Wires together:
 *   - A* pathfinding (MobilePathfindingEngine)
 *   - Turn-by-turn direction generation (generateDirections)
 *   - Route selection (start/destination NavNode)
 *
 * Exposes a discriminated union of phases so the UI can react
 * to each phase without knowing the internal routing details.
 */

import type { NavNode } from '../../src/shared/types';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
  RouteMode,
} from '../domain/navGraph';
import { MobilePathfindingEngine } from './pathfindingEngine';
import { generateDirections } from './generateDirections';

// ============================================================
// Phase types
// ============================================================

/**
 * Route session phases — a discriminated union tag.
 *
 * idle        → no start AND no destination selected
 * computing   → both nodes selected; pathfinder is running
 * ready       → route found; DirectionsResult available
 * no-route    → both nodes selected; no path exists
 * error       → one or both nodes not in graph, or unexpected failure
 */
export type RouteSessionPhase =
  | 'idle'
  | 'computing'
  | 'ready'
  | 'no-route'
  | 'error';

// ── Phase states ──────────────────────────────────────────────

export interface RouteSessionStateIdle {
  readonly phase: 'idle';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly mode: RouteMode;
  readonly pathResult: null;
  readonly directionsResult: null;
  readonly errorMessage: null;
}

export interface RouteSessionStateComputing {
  readonly phase: 'computing';
  readonly start: NavNode;
  readonly destination: NavNode;
  readonly mode: RouteMode;
  readonly pathResult: null;
  readonly directionsResult: null;
  readonly errorMessage: null;
}

export interface RouteSessionStateReady {
  readonly phase: 'ready';
  readonly start: NavNode;
  readonly destination: NavNode;
  readonly mode: RouteMode;
  readonly pathResult: PathResult;
  readonly directionsResult: DirectionsResult;
  readonly errorMessage: null;
}

export interface RouteSessionStateNoRoute {
  readonly phase: 'no-route';
  readonly start: NavNode;
  readonly destination: NavNode;
  readonly mode: RouteMode;
  readonly pathResult: PathResult;
  readonly directionsResult: null;
  readonly errorMessage: null;
}

export interface RouteSessionStateError {
  readonly phase: 'error';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly mode: RouteMode;
  readonly pathResult: null;
  readonly directionsResult: null;
  readonly errorMessage: string;
}

export type RouteSessionState =
  | RouteSessionStateIdle
  | RouteSessionStateComputing
  | RouteSessionStateReady
  | RouteSessionStateNoRoute
  | RouteSessionStateError;

// ── Options ────────────────────────────────────────────────────

export interface RouteSessionOptions {
  readonly graph: NormalizedNavGraph;
  readonly mode: RouteMode;
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Core computation
// ============================================================

/**
 * Compute the next route session state given current selection and options.
 *
 * This is a pure function — no side effects, no hooks.
 *
 * Phase transitions:
 *   idle + start===null || destination===null          → idle
 *   computing + both selected + path found             → ready
 *   computing + both selected + path not found        → no-route
 *   any  + node not in graph                           → error
 */
export function computeRouteSession(options: RouteSessionOptions): RouteSessionState {
  const { graph, mode, start, destination } = options;

  // ── Guard: incomplete selection ─────────────────────────────
  if (start === null || destination === null) {
    return {
      phase: 'idle',
      start,
      destination,
      mode,
      pathResult: null,
      directionsResult: null,
      errorMessage: null,
    };
  }

  // ── Guard: node not in graph ─────────────────────────────────
  if (!graph.nodeById.has(start.id) || !graph.nodeById.has(destination.id)) {
    const missing: string[] = [];
    if (!graph.nodeById.has(start.id)) missing.push(start.id);
    if (!graph.nodeById.has(destination.id)) missing.push(destination.id);
    return {
      phase: 'error',
      start,
      destination,
      mode,
      pathResult: null,
      directionsResult: null,
      errorMessage: `Node(s) not found in graph: ${missing.join(', ')}`,
    };
  }

  // ── Computing phase (placeholder — computation is synchronous) ─
  // We report 'computing' briefly in the UI; the actual computation below is fast
  // enough that we return the resolved state directly.

  // ── Run pathfinder ────────────────────────────────────────────
  const engine = new MobilePathfindingEngine(graph);
  const pathResult = engine.findRoute(start.id, destination.id, mode);

  if (!pathResult.found) {
    return {
      phase: 'no-route',
      start,
      destination,
      mode,
      pathResult,
      directionsResult: null,
      errorMessage: null,
    };
  }

  // ── Generate directions ───────────────────────────────────────
  const nodeMap = new Map<string, NavNode>();
  for (const record of graph.nodeById.values()) {
    nodeMap.set(record.node.id, record.node);
  }

  const directionsResult = generateDirections(
    pathResult.nodeIds,
    nodeMap,
    mode,
    graph.floorById,
  );

  return {
    phase: 'ready',
    start,
    destination,
    mode,
    pathResult,
    directionsResult,
    errorMessage: null,
  };
}

/**
 * useRouteSession — React hook wrapping the route session state machine.
 *
 * Consumers pass in:
 *   graph     — the normalized nav graph (from normalizeNavGraph / useNavGraph)
 *   selection — RouteSelection from useRouteSelection (or equivalent)
 *
 * The hook exposes:
 *   sessionState — RouteSessionState discriminated union (idle | computing | ready | no-route | error)
 *   routeMode    — current 'standard' | 'accessible'
 *   setRouteMode  — toggle between standard and accessible mode
 */

import { useCallback, useMemo, useState } from 'react';

import type { NavNode } from '../../src/shared/types';
import type { NormalizedNavGraph, RouteMode } from '../domain/navGraph';
import { computeRouteSession } from './routeSessionState';

// ── RouteSelection shape (mirrors ../hooks/useRouteSelection) ────

export interface RouteSelection {
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ── Hook return type ────────────────────────────────────────────

export interface UseRouteSessionReturn {
  /** Route session state — UI switches on sessionState.phase */
  readonly sessionState: import('./routeSessionState').RouteSessionState;
  /** Current routing mode */
  readonly routeMode: RouteMode;
  /** Switch between 'standard' and 'accessible' */
  readonly setRouteMode: (mode: RouteMode) => void;
  /** Convenience toggle — flips between 'standard' and 'accessible' */
  readonly toggleRouteMode: () => void;
}

// ── Hook ───────────────────────────────────────────────────────

/**
 * Manages the full route session lifecycle:
 *   - Re-computes whenever graph or selection changes
 *   - Tracks routing mode (standard / accessible) in local state
 */
export function useRouteSession(
  graph: NormalizedNavGraph,
  selection: RouteSelection,
): UseRouteSessionReturn {
  const [routeMode, setRouteMode] = useState<RouteMode>('standard');

  const sessionState = useMemo(
    () =>
      computeRouteSession({
        graph,
        mode: routeMode,
        start: selection.start,
        destination: selection.destination,
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [graph, selection.start, selection.destination, routeMode],
  );

  const toggleRouteMode = useCallback(() => {
    setRouteMode((prev) => (prev === 'standard' ? 'accessible' : 'standard'));
  }, []);

  return { sessionState, routeMode, setRouteMode, toggleRouteMode };
}

