/**
 * Tests for useRouteSelection hook (mobile port).
 */

import { act, renderHook } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import { useRouteSelection } from './useRouteSelection';
import type { NavNode } from '../../src/shared/types';

const roomA: NavNode = {
  id: 'room-a', x: 0.1, y: 0.5, floorId: 1, type: 'room',
  searchable: true, label: 'Room A', roomNumber: '101', description: 'Room A',
};
const roomB: NavNode = {
  id: 'room-b', x: 0.5, y: 0.5, floorId: 1, type: 'room',
  searchable: true, label: 'Room B', roomNumber: '102', description: 'Room B',
};
const roomC: NavNode = {
  id: 'room-c', x: 0.9, y: 0.5, floorId: 1, type: 'room',
  searchable: true, label: 'Room C', roomNumber: '103', description: 'Room C',
};

describe('useRouteSelection', () => {
  describe('initial state', () => {
    it('starts with null start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
    });

    it('starts with activeField = start', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.activeField).toBe('start');
    });

    it('starts with bothSelected = false', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.bothSelected).toBe(false);
    });
  });

  describe('setStart / setDestination', () => {
    it('setStart sets start and advances activeField to destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });

      expect(result.current.start?.id).toBe('room-a');
      expect(result.current.activeField).toBe('destination');
    });

    it('setDestination sets destination and advances activeField to start', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(roomB);
      });

      expect(result.current.destination?.id).toBe('room-b');
      expect(result.current.activeField).toBe('start');
    });

    it('setStart then setDestination satisfies bothSelected', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });
      act(() => {
        result.current.setDestination(roomB);
      });

      expect(result.current.bothSelected).toBe(true);
      expect(result.current.start?.id).toBe('room-a');
      expect(result.current.destination?.id).toBe('room-b');
    });
  });

  describe('setFromTap', () => {
    it('setFromTap with activeField=start sets start and advances', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setFromTap(roomA);
      });

      expect(result.current.start?.id).toBe('room-a');
      expect(result.current.activeField).toBe('destination');
    });

    it('setFromTap with activeField=destination sets destination and advances', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setActiveField('destination');
      });
      act(() => {
        result.current.setFromTap(roomB);
      });

      expect(result.current.destination?.id).toBe('room-b');
      expect(result.current.activeField).toBe('start');
    });

    it('setFromTap with activeField=start on destination node swaps start↔destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      // First set destination
      act(() => {
        result.current.setDestination(roomB);
      });
      // Now activeField = 'start'; tapping destination should swap
      act(() => {
        result.current.setFromTap(roomB);
      });

      // start = roomB (former dest), destination = roomB (same node)
      // Wait — the implementation swaps: setDestinationState(start) = null
      // setStartState(node) = roomB → start=roomB, dest=null
      expect(result.current.start?.id).toBe('room-b');
      expect(result.current.destination).toBeNull();
    });

    it('setFromTap skips duplicate when tapping same field node', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setFromTap(roomA);
      });
      act(() => {
        result.current.setActiveField('start');
      });

      // Tapping same node while activeField=start should just set start again
      act(() => {
        result.current.setFromTap(roomA);
      });

      expect(result.current.start?.id).toBe('room-a');
      expect(result.current.activeField).toBe('destination');
    });

    it('full flow: tap roomA → activeField=destination, tap roomB → bothSelected', () => {
      const { result } = renderHook(() => useRouteSelection());

      expect(result.current.activeField).toBe('start');

      act(() => {
        result.current.setFromTap(roomA);
      });
      expect(result.current.activeField).toBe('destination');
      expect(result.current.bothSelected).toBe(false);

      act(() => {
        result.current.setFromTap(roomB);
      });
      expect(result.current.activeField).toBe('start');
      expect(result.current.bothSelected).toBe(true);
    });
  });

  describe('swap', () => {
    it('swap exchanges start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });
      act(() => {
        result.current.setDestination(roomB);
      });

      act(() => {
        result.current.swap();
      });

      expect(result.current.start?.id).toBe('room-b');
      expect(result.current.destination?.id).toBe('room-a');
    });

    it('swap with null nodes does nothing harmful', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.swap();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
    });

    it('swap with only start set exchanges start with null', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });

      act(() => {
        result.current.swap();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination?.id).toBe('room-a');
    });
  });

  describe('clearAll', () => {
    it('clearAll resets all state to initial', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });
      act(() => {
        result.current.setDestination(roomB);
      });

      act(() => {
        result.current.clearAll();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
      expect(result.current.activeField).toBe('start');
      expect(result.current.bothSelected).toBe(false);
    });
  });

  describe('clearStart / clearDestination', () => {
    it('clearStart resets start and sets activeField to start', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });
      act(() => {
        result.current.setDestination(roomB);
      });

      act(() => {
        result.current.clearStart();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination?.id).toBe('room-b');
      expect(result.current.activeField).toBe('start');
    });

    it('clearDestination resets destination and sets activeField to destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(roomA);
      });
      act(() => {
        result.current.setDestination(roomB);
      });

      act(() => {
        result.current.clearDestination();
      });

      expect(result.current.start?.id).toBe('room-a');
      expect(result.current.destination).toBeNull();
      expect(result.current.activeField).toBe('destination');
    });
  });
});

