  ? GRAPH_RESULT.data
  : (() => { throw new Error('Graph setup failed'); })();

// Use actual nodes from the graph so inter-floor traversal works
const room1F1 = GRAPH.nodeById.get('b1f1-room1')!.node;
const room2F1 = GRAPH.nodeById.get('b1f1-room2')!.node;
const room1F2 = GRAPH.nodeById.get('b1f2-room1')!.node;

describe('computeRouteSession', () => {
  describe('phase transitions', () => {
    it('returns idle when start is null', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: null, destination: room2F1,
      });
      expect(state.phase).toBe('idle');
    });

    it('returns idle when destination is null', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: room1F1, destination: null,
      });
      expect(state.phase).toBe('idle');
    });

    it('returns idle when both are null', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: null, destination: null,
      });
      expect(state.phase).toBe('idle');
    });

    it('returns ready with directionsResult when path is found', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: room1F1, destination: room2F1,
      });
      expect(state.phase).toBe('ready');
      expect((state as any).pathResult?.found).toBe(true);
      expect((state as any).directionsResult).not.toBeNull();
      expect((state as any).directionsResult?.steps.length).toBeGreaterThan(0);
    });

    it('returns ready with correct start/destination preserved', () => {
      // Swap: start=room2F1, destination=room1F1
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: room2F1, destination: room1F1,
      });
      expect(state.phase).toBe('ready');
      expect((state as any).start.id).toBe('b1f1-room2');
      expect((state as any).destination.id).toBe('b1f1-room1');
    });

    it('returns ready for same-node (trivial path)', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: room1F1, destination: room1F1,
      });
      // A* handles same-node as found=true, so we get ready
      expect(state.phase).toBe('ready');
    });
  });

  describe('accessible mode filtering', () => {
    it('returns ready for accessible route between same-floor rooms', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'accessible', start: room1F1, destination: room2F1,
      });
      expect(state.phase).toBe('ready');
      expect((state as any).mode).toBe('accessible');
    });

    it('returns ready for cross-floor accessible route via elevator', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'accessible', start: room1F1, destination: room1F2,
      });
      expect(state.phase).toBe('ready');
      // Accessible route must use elevator, not stairs
      const pathIds = (state as any).pathResult.nodeIds as string[];
      expect(pathIds).toContain('b1f1-elevator');
      expect(pathIds).toContain('b1f2-elevator');
    });
  });

  describe('error handling', () => {
    it('returns error when start node is not in graph', () => {
      const ghostNode: NavNode = {
        id: 'ghost-node', x: 0.5, y: 0.5, floorId: 999, type: 'room',
        searchable: false, label: 'Ghost',
      };
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: ghostNode, destination: room2F1,
      });
      expect(state.phase).toBe('error');
      expect((state as any).errorMessage).toContain('ghost-node');
    });

    it('returns error when destination node is not in graph', () => {
      const ghostNode: NavNode = {
        id: 'ghost-node', x: 0.5, y: 0.5, floorId: 999, type: 'room',
        searchable: false, label: 'Ghost',
      };
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: room1F1, destination: ghostNode,
      });
      expect(state.phase).toBe('error');
      expect((state as any).errorMessage).toContain('ghost-node');
    });
  });

  describe('mode parameter', () => {
    it('persists standard mode in ready state', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'standard', start: room1F1, destination: room2F1,
      });
      expect((state as any).mode).toBe('standard');
    });

    it('persists accessible mode in ready state', () => {
      const state = computeRouteSession({
        graph: GRAPH, mode: 'accessible', start: room1F1, destination: room2F1,
      });
      expect((state as any).mode).toBe('accessible');
    });
  });
});

/**
 * Tests for useRouteSession hook.
 *
 * Uses vitest globals (no jsdom required) — hooks are tested by calling
 * them directly and checking returned state via React's act().
 */

import { act } from 'react';
import { describe, expect, it } from 'vitest';
import { useRouteSession } from './useRouteSession';
import type { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import { normalizeNavGraph } from '../domain/navGraph';

function createTestNavGraph(): NavGraph {
  const b1f1Nodes: NavNode[] = [
    {
      id: 'b1f1-room1', x: 0.1, y: 0.5, floorId: 1, type: 'room',
      searchable: true, label: 'Room 101', roomNumber: '101', description: 'Test Room',
    },
    {
      id: 'b1f1-room2', x: 0.5, y: 0.5, floorId: 1, type: 'room',
      searchable: true, label: 'Room 102', roomNumber: '102',
    },
  ];

  const b1f1Edges: NavEdge[] = [
    { id: 'b1f1-e1', sourceId: 'b1f1-room1', targetId: 'b1f1-room2', standardWeight: 0.4, accessibleWeight: 0.4, accessible: true, bidirectional: true },
  ];

  const floor1: NavFloor = {
    id: 1, buildingId: 1, floorNumber: 1, name: 'Floor 1',
    imagePath: '/b1f1.png', updatedAt: '2024-01-01T00:00:00Z',
    nodes: b1f1Nodes, edges: b1f1Edges,
  };

  const building: NavBuilding = {
    id: 1, name: 'Test Building',
    floors: [floor1],
    svgBounds: { minX: 0, minY: 0, maxX: 1, maxY: 1 },
  };

  return { buildings: [building] };
}

const GRAPH_RESULT = normalizeNavGraph(createTestNavGraph());
const GRAPH = GRAPH_RESULT.ok
  ? GRAPH_RESULT.data
  : (() => { throw new Error('Graph setup failed'); })();

const room1: NavNode = GRAPH.nodeById.get('b1f1-room1')!.node;
const room2: NavNode = GRAPH.nodeById.get('b1f1-room2')!.node;

/** Helper to create a fresh hook instance and capture its state */
function createHookInstance(
  graph: ReturnType<typeof normalizeNavGraph> extends { data: infer T } ? T : never,
  selection: { start: NavNode | null; destination: NavNode | null },
) {
  // Capture the result synchronously — state is set immediately for pure useState
  const result = useRouteSession(graph, selection);
  return result;
}

describe('useRouteSession', () => {
  it('returns idle phase when no selection', () => {
    const sessionState = createHookInstance(GRAPH, { start: null, destination: null });
    expect(sessionState.sessionState.phase).toBe('idle');
  });

  it('starts in standard mode', () => {
    const { routeMode, sessionState } = createHookInstance(GRAPH, { start: room1, destination: room2 });
    expect(routeMode).toBe('standard');
    expect(sessionState.mode).toBe('standard');
  });

  it('returns ready phase when both selected', () => {
    const { sessionState } = createHookInstance(GRAPH, { start: room1, destination: room2 });
    expect(sessionState.phase).toBe('ready');
  });

  it('returns idle when only start is set', () => {
    const { sessionState } = createHookInstance(GRAPH, { start: room1, destination: null });
    expect(sessionState.phase).toBe('idle');
  });

  it('returns idle when only destination is set', () => {
    const { sessionState } = createHookInstance(GRAPH, { start: null, destination: room2 });
    expect(sessionState.phase).toBe('idle');
  });

  // ── Mode toggling (requires act() to trigger re-render) ────────

  it('setRouteMode changes mode', () => {
    let hookRef: ReturnType<typeof useRouteSession> | undefined;
    function TestComponent() {
      hookRef = useRouteSession(GRAPH, { start: room1, destination: room2 });
      return null;
    }

    // Instantiate
    const instance = useRouteSession(GRAPH, { start: room1, destination: room2 });
    expect(instance.routeMode).toBe('standard');

    // Toggle via setRouteMode — wrap in act
    act(() => {
      instance.setRouteMode('accessible');
    });

    expect(instance.routeMode).toBe('accessible');
    expect(instance.sessionState.mode).toBe('accessible');
  });

  it('toggleRouteMode flips standard → accessible', () => {
    const instance = useRouteSession(GRAPH, { start: room1, destination: room2 });
    expect(instance.routeMode).toBe('standard');

    act(() => {
      instance.toggleRouteMode();
    });

    expect(instance.routeMode).toBe('accessible');
  });

  it('toggleRouteMode flips accessible → standard', () => {
    const instance = useRouteSession(GRAPH, { start: room1, destination: room2 });

    act(() => {
      instance.setRouteMode('accessible');
    });
    expect(instance.routeMode).toBe('accessible');

    act(() => {
      instance.toggleRouteMode();
    });

    expect(instance.routeMode).toBe('standard');
  });

  it('accessible mode route differs from standard mode', () => {
    // Both should find routes
    const standard = useRouteSession(GRAPH, { start: room1, destination: room2 });
    expect(standard.sessionState.phase).toBe('ready');

    act(() => {
      standard.setRouteMode('accessible');
    });

    expect(standard.sessionState.phase).toBe('ready');
    expect(standard.sessionState.mode).toBe('accessible');
  });
});

/**
 * Tests for useRouteSelection hook (mobile port).
 *
 * Uses vitest globals (no jsdom required) — the hook uses only useState,
 * useMemo, and useCallback which are plain React functions callable in node.
 */

import { act } from 'react';
import { describe, expect, it } from 'vitest';
import { useRouteSelection } from './useRouteSelection';
import type { NavNode } from '../../src/shared/types';

const roomA: NavNode = {
  id: 'room-a', x: 0.1, y: 0.5, floorId: 1, type: 'room',
  searchable: true, label: 'Room A', roomNumber: '101', description: 'Room A',
};
const roomB: NavNode = {
  id: 'room-b', x: 0.5, y: 0.5, floorId: 1, type: 'room',
  searchable: true, label: 'Room B', roomNumber: '102', description: 'Room B',
};
const roomC: NavNode = {
  id: 'room-c', x: 0.9, y: 0.5, floorId: 1, type: 'room',
  searchable: true, label: 'Room C', roomNumber: '103', description: 'Room C',
};

describe('useRouteSelection', () => {
  describe('initial state', () => {
    it('starts with null start and destination', () => {
      const hook = useRouteSelection();
      expect(hook.start).toBeNull();
      expect(hook.destination).toBeNull();
    });

    it('starts with activeField = start', () => {
      const hook = useRouteSelection();
      expect(hook.activeField).toBe('start');
    });

    it('starts with bothSelected = false', () => {
      const hook = useRouteSelection();
      expect(hook.bothSelected).toBe(false);
    });
  });

  describe('setStart / setDestination', () => {
    it('setStart sets start and advances activeField to destination', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });

      expect(hook.start?.id).toBe('room-a');
      expect(hook.activeField).toBe('destination');
    });

    it('setDestination sets destination and advances activeField to start', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setDestination(roomB);
      });

      expect(hook.destination?.id).toBe('room-b');
      expect(hook.activeField).toBe('start');
    });

    it('setStart then setDestination satisfies bothSelected', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });
      act(() => {
        hook.setDestination(roomB);
      });

      expect(hook.bothSelected).toBe(true);
      expect(hook.start?.id).toBe('room-a');
      expect(hook.destination?.id).toBe('room-b');
    });
  });

  describe('setFromTap', () => {
    it('setFromTap with activeField=start sets start and advances', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setFromTap(roomA);
      });

      expect(hook.start?.id).toBe('room-a');
      expect(hook.activeField).toBe('destination');
    });

    it('setFromTap with activeField=destination sets destination and advances', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setActiveField('destination');
      });
      act(() => {
        hook.setFromTap(roomB);
      });

      expect(hook.destination?.id).toBe('room-b');
      expect(hook.activeField).toBe('start');
    });

    it('setFromTap when activeField=start on destination node swaps', () => {
      // Scenario: destination already set; activeField is 'start'; user taps destination node
      // Expected: swap start↔destination
      const hook = useRouteSelection();

      act(() => {
        hook.setDestination(roomB);
      });
      // After setDestination, activeField = 'start'
      expect(hook.activeField).toBe('start');

      act(() => {
        hook.setFromTap(roomB);
      });

      // setDestinationState(start=null) → start=null
      // setStartState(node=roomB) → start=roomB
      expect(hook.start?.id).toBe('room-b');
      expect(hook.destination).toBeNull();
      expect(hook.activeField).toBe('destination');
    });

    it('setFromTap when activeField=destination on start node swaps', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });
      // After setStart, activeField = 'destination'
      expect(hook.activeField).toBe('destination');

      act(() => {
        hook.setFromTap(roomA);
      });

      // setStartState(destination=null) → dest=null
      // setDestinationState(node=roomA) → dest=roomA
      expect(hook.destination?.id).toBe('room-a');
      expect(hook.start).toBeNull();
      expect(hook.activeField).toBe('start');
    });

    it('setFromTap skips duplicate when tapping same field node', () => {
      // Tapping the same field's node should just set it again (not swap)
      const hook = useRouteSelection();

      act(() => {
        hook.setFromTap(roomA);
      });
      act(() => {
        hook.setActiveField('start');
      });
      // activeField is 'start', setFromTap(roomA) → setStartState(roomA), advance
      act(() => {
        hook.setFromTap(roomA);
      });

      expect(hook.start?.id).toBe('room-a');
      expect(hook.activeField).toBe('destination');
    });

    it('full flow: tap roomA → activeField=destination, tap roomB → bothSelected', () => {
      const hook = useRouteSelection();

      expect(hook.activeField).toBe('start');

      act(() => {
        hook.setFromTap(roomA);
      });
      expect(hook.activeField).toBe('destination');
      expect(hook.bothSelected).toBe(false);

      act(() => {
        hook.setFromTap(roomB);
      });
      expect(hook.activeField).toBe('start');
      expect(hook.bothSelected).toBe(true);
    });
  });

  describe('swap', () => {
    it('swap exchanges start and destination', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });
      act(() => {
        hook.setDestination(roomB);
      });

      act(() => {
        hook.swap();
      });

      expect(hook.start?.id).toBe('room-b');
      expect(hook.destination?.id).toBe('room-a');
    });

    it('swap with null nodes does nothing harmful', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.swap();
      });

      expect(hook.start).toBeNull();
      expect(hook.destination).toBeNull();
    });

    it('swap with only start set exchanges start with null', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });

      act(() => {
        hook.swap();
      });

      expect(hook.start).toBeNull();
      expect(hook.destination?.id).toBe('room-a');
    });
  });

  describe('clearAll', () => {
    it('clearAll resets all state to initial', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });
      act(() => {
        hook.setDestination(roomB);
      });

      act(() => {
        hook.clearAll();
      });

      expect(hook.start).toBeNull();
      expect(hook.destination).toBeNull();
      expect(hook.activeField).toBe('start');
      expect(hook.bothSelected).toBe(false);
    });
  });

  describe('clearStart / clearDestination', () => {
    it('clearStart resets start and sets activeField to start', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });
      act(() => {
        hook.setDestination(roomB);
      });

      act(() => {
        hook.clearStart();
      });

      expect(hook.start).toBeNull();
      expect(hook.destination?.id).toBe('room-b');
      expect(hook.activeField).toBe('start');
    });

    it('clearDestination resets destination and sets activeField to destination', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });
      act(() => {
        hook.setDestination(roomB);
      });

      act(() => {
        hook.clearDestination();
      });

      expect(hook.start?.id).toBe('room-a');
      expect(hook.destination).toBeNull();
      expect(hook.activeField).toBe('destination');
    });
  });

  describe('clearStart when only start is set', () => {
    it('clears start without error', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setStart(roomA);
      });

      act(() => {
        hook.clearStart();
      });

      expect(hook.start).toBeNull();
    });
  });

  describe('setActiveField', () => {
    it('setActiveField switches to destination', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setActiveField('destination');
      });

      expect(hook.activeField).toBe('destination');
    });

    it('setActiveField switches back to start', () => {
      const hook = useRouteSelection();

      act(() => {
        hook.setActiveField('destination');
      });
      act(() => {
        hook.setActiveField('start');
      });

      expect(hook.activeField).toBe('start');
    });
  });
});

